def-hyp(
    __list__(
        Type.annotation(@a, Nat),
        Type.annotation(@b, Nat)
    ),
    Add.add(a, b),
    by-cases(
        b,
        __enum__(
            member[colon](
                Eq(b, %zero%@Set.example.nat), Type.lambda-typed(a, Nat, a)
            ),
            member[colon](
                Logic.exists-typed(@n, Nat, Eq(b, Type.apply(%succ%@Set.example.nat, n))),
                Type.apply(%succ%@Set.example.nat, Add.add(a, n))
            )
        )
    )
)
